from svg import box, t, line, svg

ROWS = [('Had a self before', 'yes, a whole life', 'no before at all'),
        ('Chose to join', 'yes, under pressure', 'never chose'),
        ('Leaving costs', 'friends, a world', 'parents, siblings, everything'),
        ('Knows the outside', 'remembers it', 'learns it like a migrant'),
        ('Recovery task', 'return to a self', 'build one from scratch')]
FIG = svg(1180, 440, 'Converts versus people born inside a high-demand group',
          box(20, 20, 1140, 400, 's-card') + box(760, 40, 340, 368, 's-box-a', 12) +
          t(560, 70, 'CONVERT', 's-t') + t(930, 70, 'BORN INSIDE', 's-t') + line(40, 90, 1140, 90) +
          ''.join(t(50, 136 + i * 62, a, 's-t-b', 'start') + t(560, 136 + i * 62, b, 's-t-sm') + t(930, 136 + i * 62, c, 's-t-sm') +
                  (line(40, 158 + i * 62, 1140, 158 + i * 62, dash=True) if i < 4 else '') for i, (a, b, c) in enumerate(ROWS)))

